const text = $('Edit Fields5').first().json.text;
const chunkSize = 1000;
const chunkOverlap = 200;
const overlapBoundary = 'word';
const separators = ['\n\n', '\n', ' ', ''];

const result = [];
let start = 0;
let chunkIndex = 0;

while (start < text.length) {
  let end = Math.min(start + chunkSize, text.length);

  // Ajustar el final del chunk según el overlapBoundary
  if (overlapBoundary === 'word') {
    while (end < text.length && ![' ', '\n'].includes(text[end])) {
      end++;
    }
  } else if (overlapBoundary === 'sentence') {
    while (end < text.length && !['.', '!', '?'].includes(text[end])) {
      end++;
    }
    end++; // incluir el signo de puntuación
  }

  let chunk = text.slice(start, end).trim();

  // Aplicar el primer separador válido
  for (const sep of separators) {
    if (chunk.includes(sep)) {
      chunk = chunk.split(sep).join(sep); // sin modificar, pero referencia usada
      break;
    }
  }

  result.push({
    json: {
      chunk,
      chunkIndex,
    }
  });

  start += chunkSize - chunkOverlap;
  chunkIndex++;
}

return result;

const isCached = $('Code2').all().length > 0;
const cachedContext = isCached ? $('Code2').first().json.name : null;

const output = $input.all().map(item => {
  const chunk = item.json.chunk;

  const noCachePrompt = `Tienes el fragmento del documento a continuación:

<chunk>
${chunk}
</chunk>

Por favor, proporciona un resumen breve para fines de recuperación.`;

  const cachedPrompt = `Tienes el documento dentro de la caché de contexto.

<chunk>
${chunk}
</chunk>
Proporciona un contexto breve y conciso para situar este fragmento dentro del documento completo, con el objetivo de mejorar la recuperación por búsqueda del fragmento. Responde solo con el contexto conciso y nada más.`;

  const thePrompt = isCached
    ? {
        prompt: {
          json: {
            contents: [
              {
                parts: [{ text: cachedPrompt }],
                role: "user",
              },
            ],
            cachedContent: cachedContext,
          },
        },
      }
    : {
        prompt: {
          json: {
            contents: [
              {
                parts: [{ text: noCachePrompt }],
                role: "user",
              },
            ],
          },
        },
      };

  return {
    json: {
      ...item.json,
      thePrompt,
    },
  };
});

return output;

